'use strict';

// Builds what the website's AI support may answer from (cloudflare/status-worker/src/supportKnowledge.mjs): the public
// feature list, the public slash commands, the policy blocks of the support dialog and the self-help questions, all
// taken from the website's own files. Nothing private (no private command, server or path) is in those files, and
// test/websiteSupport.test.js checks that the generated file matches them.
//
//   node scripts/build-support-knowledge.js          writes the file
//   node scripts/build-support-knowledge.js --check  exits 1 when the file is out of date

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const OUTPUT = path.join(ROOT, 'cloudflare', 'status-worker', 'src', 'supportKnowledge.mjs');

function policyBlocks(siteSupportSource) {
  const blocks = [];
  for (const line of siteSupportSource.split('\n')) {
    const match = /^\s+\['([^']+)', '([^']+)'\],$/u.exec(line);
    if (match) blocks.push([match[1], match[2]]);
  }
  return blocks;
}

function faqs(siteSupportSource) {
  const result = [];
  for (const match of siteSupportSource.matchAll(/\{ title: '([^']+)', keywords: \[[^\]]*\], answer: '([^']+)'/gu)) {
    if (match[1] !== '其他問題') result.push([match[1], match[2]]);
  }
  return result;
}

function buildKnowledge() {
  const { PUBLIC_SYSTEM_CATALOG } = require(path.join(ROOT, 'src', 'platform', 'catalogs', 'publicFeatureCatalog.js'));
  const { COMMAND_CATALOG } = require(path.join(ROOT, 'src', 'platform', 'catalogs', 'commandCatalog.js'));
  const siteSupport = fs.readFileSync(path.join(ROOT, 'website', 'siteSupport.js'), 'utf8');
  const lines = ['# 小吉的公開功能'];
  for (const system of PUBLIC_SYSTEM_CATALOG) {
    lines.push(`## ${system.name}`);
    for (const feature of system.features) {
      lines.push(`- ${feature.name}：${feature.purpose} 使用方式：${feature.howTo} 限制：${feature.limitation}`);
    }
  }
  lines.push('', '# 公開斜線指令');
  for (const command of COMMAND_CATALOG.filter((entry) => entry.listInHelp && entry.audience !== 'owner')) {
    lines.push(`- /${command.name}：${command.description}${command.audience === 'admin' ? '（需要伺服器管理權限）' : ''}`);
  }
  lines.push('', '# 使用者政策與隱私權政策重點');
  for (const [heading, text] of policyBlocks(siteSupport)) lines.push(`- ${heading}：${text.replace(/\$\{[^}]*\}/gu, '')}`);
  lines.push('', '# 常見問題');
  for (const [title, answer] of faqs(siteSupport)) lines.push(`- ${title}：${answer}`);
  lines.push('', '# 聯絡方式', '- 需要人工處理時，請寄信到 xichengyu810067@gmail.com，主旨用「小吉服務詢問」。');
  return lines.join('\n');
}

function render(knowledge = buildKnowledge()) {
  return [
    '// Generated by scripts/build-support-knowledge.js from the website\'s public files. Do not edit by hand.',
    `export const SUPPORT_KNOWLEDGE = ${JSON.stringify(knowledge)};`,
    '',
  ].join('\n');
}

if (require.main === module) {
  const expected = render();
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(OUTPUT) ? fs.readFileSync(OUTPUT, 'utf8') : '';
    if (current !== expected) {
      console.error('supportKnowledge.mjs is out of date: run node scripts/build-support-knowledge.js');
      process.exit(1);
    }
  } else {
    fs.writeFileSync(OUTPUT, expected, 'utf8');
    console.log(`Wrote ${path.relative(ROOT, OUTPUT)} (${expected.length} characters).`);
  }
}

module.exports = { buildKnowledge, render };
